-- TestFlight 0.0.1 (166), commit 9ea2ad492a7da2c05fe5c3510a6dbb8c09a326e1.
-- Release schema definitions; synthetic fixture, no player data.
CREATE TABLE course_scores (id INTEGER PRIMARY KEY AUTOINCREMENT,course_id INTEGER,course_key TEXT,legacy_course_key TEXT NOT NULL DEFAULT '',ln_mode INTEGER NOT NULL DEFAULT -1,course_name TEXT,course_group_name TEXT,constraint_json TEXT,gauge_type INTEGER NOT NULL,gauge_profile INTEGER NOT NULL,gauge_auto_shift INTEGER NOT NULL,play_option TEXT,assist_option TEXT,completed_charts INTEGER NOT NULL,total_charts INTEGER NOT NULL,score INTEGER NOT NULL,max_score INTEGER NOT NULL,max_combo INTEGER NOT NULL,combo_break INTEGER NOT NULL,pgreat INTEGER NOT NULL,great INTEGER NOT NULL,good INTEGER NOT NULL,bad INTEGER NOT NULL,poor INTEGER NOT NULL,kpoor INTEGER NOT NULL,bad_points INTEGER CHECK(bad_points>=0),fast INTEGER NOT NULL,slow INTEGER NOT NULL,final_gauge REAL NOT NULL,clear_type INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,ruleset_version INTEGER NOT NULL DEFAULT 0,eligibility INTEGER NOT NULL DEFAULT 2,provenance_json TEXT NOT NULL DEFAULT '{"schemaVersion":1,"ruleset":{"version":0},"stages":[],"eligibility":"legacy-unverified"}',attempt_id TEXT,modern_result_id INTEGER,result_fingerprint TEXT);
CREATE TABLE score_data_repair_state(completed INTEGER NOT NULL PRIMARY KEY CHECK(completed=1)) WITHOUT ROWID;
CREATE TABLE score_sha256_best_score_cache (chart_sha256 TEXT NOT NULL, ln_mode INTEGER NOT NULL, score_id INTEGER NOT NULL, score INTEGER NOT NULL, max_score INTEGER NOT NULL, max_combo INTEGER NOT NULL, combo_break INTEGER NOT NULL, final_gauge REAL NOT NULL, clear_type INTEGER NOT NULL, clear_rank INTEGER NOT NULL, score_rank TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(chart_sha256, ln_mode)) WITHOUT ROWID;
CREATE TABLE score_sha256_clear_rank_cache (chart_sha256 TEXT NOT NULL, ln_mode INTEGER NOT NULL, rank INTEGER NOT NULL, PRIMARY KEY(chart_sha256, ln_mode)) WITHOUT ROWID;
CREATE TABLE scores (id INTEGER PRIMARY KEY AUTOINCREMENT,chart_path TEXT,chart_md5 TEXT,chart_sha256 TEXT NOT NULL,ln_mode INTEGER NOT NULL DEFAULT 0,chart_title TEXT,chart_artist TEXT,score INTEGER NOT NULL,max_score INTEGER NOT NULL,max_combo INTEGER NOT NULL,combo_break INTEGER NOT NULL,pgreat INTEGER NOT NULL,great INTEGER NOT NULL,good INTEGER NOT NULL,bad INTEGER NOT NULL,poor INTEGER NOT NULL,kpoor INTEGER NOT NULL,bad_points INTEGER,average_judge_micros INTEGER,fast INTEGER NOT NULL,slow INTEGER NOT NULL,final_gauge REAL NOT NULL,clear_type INTEGER NOT NULL,play_duration_seconds INTEGER NOT NULL DEFAULT 0 CHECK(play_duration_seconds BETWEEN 0 AND 2147483647),score_source INTEGER NOT NULL DEFAULT 0,source_provider_id TEXT,source_server_origin TEXT,source_remote_score_id TEXT,source_sync_generation INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,ruleset_version INTEGER NOT NULL DEFAULT 0,eligibility INTEGER NOT NULL DEFAULT 2,provenance_json TEXT NOT NULL DEFAULT '{"schemaVersion":1,"ruleset":{"version":0},"stages":[],"eligibility":"legacy-unverified"}',attempt_id TEXT);
CREATE UNIQUE INDEX idx_course_scores_attempt_id ON course_scores(attempt_id) WHERE attempt_id IS NOT NULL;
CREATE INDEX idx_course_scores_clear_type ON course_scores(clear_type);
CREATE INDEX idx_course_scores_course_id ON course_scores(course_id);
CREATE INDEX idx_course_scores_course_id_clear_type ON course_scores(course_id, clear_type);
CREATE INDEX idx_course_scores_course_key ON course_scores(course_key);
CREATE INDEX idx_course_scores_created_at ON course_scores(created_at);
CREATE INDEX idx_course_scores_key_ln_mode_clear_type ON course_scores(course_key, ln_mode, clear_type);
CREATE UNIQUE INDEX idx_course_scores_modern_result_id ON course_scores(modern_result_id) WHERE modern_result_id IS NOT NULL;
CREATE UNIQUE INDEX idx_scores_attempt_id ON scores(attempt_id) WHERE attempt_id IS NOT NULL;
CREATE INDEX idx_scores_best_eligible_5_4_compat1 ON scores(chart_sha256) WHERE (scores.eligibility <> 1 AND (scores.ruleset_version = 0 OR CASE WHEN json_valid(scores.provenance_json) THEN ((json_extract(scores.provenance_json, '$.ruleset.id') = 'lr2' AND json_extract(scores.provenance_json, '$.ruleset.version') = 5 AND json_extract(scores.provenance_json, '$.ruleset.scoringModel') = 'asobmashow-v1' AND json_extract(scores.provenance_json, '$.ruleset.judgementModel') = 'lr2-v1' AND json_extract(scores.provenance_json, '$.ruleset.gaugeModel') = 'lr2-gauge-v1') OR (json_extract(scores.provenance_json, '$.ruleset.id') = 'lr2' AND json_extract(scores.provenance_json, '$.ruleset.version') = 4 AND json_extract(scores.provenance_json, '$.ruleset.scoringModel') = 'asobmashow-v1' AND json_extract(scores.provenance_json, '$.ruleset.judgementModel') = 'lr2-v1' AND json_extract(scores.provenance_json, '$.ruleset.gaugeModel') = 'lr2-gauge-v1') OR (json_extract(scores.provenance_json, '$.ruleset.id') = 'beatoraja' AND json_extract(scores.provenance_json, '$.ruleset.version') = 4 AND json_extract(scores.provenance_json, '$.ruleset.scoringModel') = 'asobmashow-v1' AND json_extract(scores.provenance_json, '$.ruleset.judgementModel') = 'bms-rank-v1' AND json_extract(scores.provenance_json, '$.ruleset.gaugeModel') = 'beatoraja-profile-gauge-v2') OR (json_extract(scores.provenance_json, '$.ruleset.id') = 'beatoraja' AND json_extract(scores.provenance_json, '$.ruleset.version') = 3 AND json_extract(scores.provenance_json, '$.ruleset.scoringModel') = 'asobmashow-v1' AND json_extract(scores.provenance_json, '$.ruleset.judgementModel') = 'bms-rank-v1' AND json_extract(scores.provenance_json, '$.ruleset.gaugeModel') = 'beatoraja-profile-gauge-v2')) ELSE 0 END));
CREATE INDEX idx_scores_chart_md5 ON scores(chart_md5);
CREATE INDEX idx_scores_chart_md5_clear_type ON scores(chart_md5, clear_type);
CREATE INDEX idx_scores_chart_md5_ln_mode ON scores(chart_md5, ln_mode);
CREATE INDEX idx_scores_chart_path ON scores(chart_path);
CREATE INDEX idx_scores_chart_path_clear_type ON scores(chart_path, clear_type);
CREATE INDEX idx_scores_chart_path_ln_mode ON scores(chart_path, ln_mode);
CREATE INDEX idx_scores_chart_sha256 ON scores(chart_sha256);
CREATE INDEX idx_scores_chart_sha256_clear_type ON scores(chart_sha256, clear_type);
CREATE INDEX idx_scores_chart_sha256_ln_mode ON scores(chart_sha256, ln_mode);
CREATE INDEX idx_scores_created_at ON scores(created_at);
CREATE INDEX idx_scores_identity_ln_mode ON scores(chart_sha256, chart_md5, chart_path, ln_mode);
CREATE UNIQUE INDEX idx_scores_imported_ir_identity ON scores(source_provider_id, source_server_origin, source_remote_score_id) WHERE score_source = 1;
CREATE TRIGGER score_sha256_summary_after_insert AFTER INSERT ON scores BEGIN INSERT INTO score_sha256_clear_rank_cache(chart_sha256, ln_mode, rank) SELECT lower(trim(NEW.chart_sha256)), modes.ln_mode, (CASE WHEN NEW.score_source = 1 THEN NEW.clear_type WHEN NEW.clear_type >= 100 AND (CASE WHEN json_valid(NEW.provenance_json) THEN COALESCE(json_extract(NEW.provenance_json, '$.playback.percent'), 100) ELSE 0 END) <> 100 THEN 150 WHEN NEW.combo_break = 0 AND NEW.clear_type >= 100 THEN 600 ELSE NEW.clear_type END) FROM (SELECT 0 AS ln_mode UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3) modes WHERE (NEW.ln_mode = -1 OR NEW.ln_mode = modes.ln_mode) AND NULLIF(trim(NEW.chart_sha256), '') IS NOT NULL AND (NEW.eligibility <> 1 AND (NEW.ruleset_version = 0 OR CASE WHEN json_valid(NEW.provenance_json) THEN ((json_extract(NEW.provenance_json, '$.ruleset.id') = 'lr2' AND json_extract(NEW.provenance_json, '$.ruleset.version') = 5 AND json_extract(NEW.provenance_json, '$.ruleset.scoringModel') = 'asobmashow-v1' AND json_extract(NEW.provenance_json, '$.ruleset.judgementModel') = 'lr2-v1' AND json_extract(NEW.provenance_json, '$.ruleset.gaugeModel') = 'lr2-gauge-v1') OR (json_extract(NEW.provenance_json, '$.ruleset.id') = 'lr2' AND json_extract(NEW.provenance_json, '$.ruleset.version') = 4 AND json_extract(NEW.provenance_json, '$.ruleset.scoringModel') = 'asobmashow-v1' AND json_extract(NEW.provenance_json, '$.ruleset.judgementModel') = 'lr2-v1' AND json_extract(NEW.provenance_json, '$.ruleset.gaugeModel') = 'lr2-gauge-v1') OR (json_extract(NEW.provenance_json, '$.ruleset.id') = 'beatoraja' AND json_extract(NEW.provenance_json, '$.ruleset.version') = 4 AND json_extract(NEW.provenance_json, '$.ruleset.scoringModel') = 'asobmashow-v1' AND json_extract(NEW.provenance_json, '$.ruleset.judgementModel') = 'bms-rank-v1' AND json_extract(NEW.provenance_json, '$.ruleset.gaugeModel') = 'beatoraja-profile-gauge-v2') OR (json_extract(NEW.provenance_json, '$.ruleset.id') = 'beatoraja' AND json_extract(NEW.provenance_json, '$.ruleset.version') = 3 AND json_extract(NEW.provenance_json, '$.ruleset.scoringModel') = 'asobmashow-v1' AND json_extract(NEW.provenance_json, '$.ruleset.judgementModel') = 'bms-rank-v1' AND json_extract(NEW.provenance_json, '$.ruleset.gaugeModel') = 'beatoraja-profile-gauge-v2')) ELSE 0 END)) ON CONFLICT(chart_sha256, ln_mode) DO UPDATE SET rank = max(score_sha256_clear_rank_cache.rank, excluded.rank);INSERT INTO score_sha256_best_score_cache(chart_sha256, ln_mode, score_id, score, max_score, max_combo, combo_break, final_gauge, clear_type, clear_rank, score_rank, created_at) SELECT lower(trim(NEW.chart_sha256)), modes.ln_mode, NEW.id, NEW.score, NEW.max_score, NEW.max_combo, NEW.combo_break, NEW.final_gauge, NEW.clear_type, (CASE WHEN NEW.score_source = 1 THEN NEW.clear_type WHEN NEW.clear_type >= 100 AND (CASE WHEN json_valid(NEW.provenance_json) THEN COALESCE(json_extract(NEW.provenance_json, '$.playback.percent'), 100) ELSE 0 END) <> 100 THEN 150 WHEN NEW.combo_break = 0 AND NEW.clear_type >= 100 THEN 600 ELSE NEW.clear_type END), (CASE WHEN NEW.max_score <= 0 THEN '' WHEN max(0, NEW.score) >= NEW.max_score THEN 'MAX' WHEN max(0, NEW.score) >= ((NEW.max_score * 26 + 26) / 27) THEN 'MAX -' WHEN max(0, NEW.score) >= ((NEW.max_score * 24 + 26) / 27) THEN 'AAA' WHEN max(0, NEW.score) >= ((NEW.max_score * 21 + 26) / 27) THEN 'AA' WHEN max(0, NEW.score) >= ((NEW.max_score * 18 + 26) / 27) THEN 'A' WHEN max(0, NEW.score) >= ((NEW.max_score * 15 + 26) / 27) THEN 'B' WHEN max(0, NEW.score) >= ((NEW.max_score * 12 + 26) / 27) THEN 'C' WHEN max(0, NEW.score) >= ((NEW.max_score * 9 + 26) / 27) THEN 'D' WHEN max(0, NEW.score) >= ((NEW.max_score * 6 + 26) / 27) THEN 'E' ELSE 'F' END), NEW.created_at FROM (SELECT 0 AS ln_mode UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3) modes WHERE (NEW.ln_mode = -1 OR NEW.ln_mode = modes.ln_mode) AND NULLIF(trim(NEW.chart_sha256), '') IS NOT NULL AND (NEW.eligibility <> 1 AND (NEW.ruleset_version = 0 OR CASE WHEN json_valid(NEW.provenance_json) THEN ((json_extract(NEW.provenance_json, '$.ruleset.id') = 'lr2' AND json_extract(NEW.provenance_json, '$.ruleset.version') = 5 AND json_extract(NEW.provenance_json, '$.ruleset.scoringModel') = 'asobmashow-v1' AND json_extract(NEW.provenance_json, '$.ruleset.judgementModel') = 'lr2-v1' AND json_extract(NEW.provenance_json, '$.ruleset.gaugeModel') = 'lr2-gauge-v1') OR (json_extract(NEW.provenance_json, '$.ruleset.id') = 'lr2' AND json_extract(NEW.provenance_json, '$.ruleset.version') = 4 AND json_extract(NEW.provenance_json, '$.ruleset.scoringModel') = 'asobmashow-v1' AND json_extract(NEW.provenance_json, '$.ruleset.judgementModel') = 'lr2-v1' AND json_extract(NEW.provenance_json, '$.ruleset.gaugeModel') = 'lr2-gauge-v1') OR (json_extract(NEW.provenance_json, '$.ruleset.id') = 'beatoraja' AND json_extract(NEW.provenance_json, '$.ruleset.version') = 4 AND json_extract(NEW.provenance_json, '$.ruleset.scoringModel') = 'asobmashow-v1' AND json_extract(NEW.provenance_json, '$.ruleset.judgementModel') = 'bms-rank-v1' AND json_extract(NEW.provenance_json, '$.ruleset.gaugeModel') = 'beatoraja-profile-gauge-v2') OR (json_extract(NEW.provenance_json, '$.ruleset.id') = 'beatoraja' AND json_extract(NEW.provenance_json, '$.ruleset.version') = 3 AND json_extract(NEW.provenance_json, '$.ruleset.scoringModel') = 'asobmashow-v1' AND json_extract(NEW.provenance_json, '$.ruleset.judgementModel') = 'bms-rank-v1' AND json_extract(NEW.provenance_json, '$.ruleset.gaugeModel') = 'beatoraja-profile-gauge-v2')) ELSE 0 END)) ON CONFLICT(chart_sha256, ln_mode) DO UPDATE SET score_id = excluded.score_id, score = excluded.score, max_score = excluded.max_score, max_combo = excluded.max_combo, combo_break = excluded.combo_break, final_gauge = excluded.final_gauge, clear_type = excluded.clear_type, clear_rank = excluded.clear_rank, score_rank = excluded.score_rank, created_at = excluded.created_at WHERE (excluded.score, excluded.clear_rank, excluded.created_at, excluded.score_id) > (score_sha256_best_score_cache.score, score_sha256_best_score_cache.clear_rank, score_sha256_best_score_cache.created_at, score_sha256_best_score_cache.score_id); END;
CREATE TRIGGER scores_play_duration_insert_guard BEFORE INSERT ON scores WHEN NEW.play_duration_seconds < 0 OR NEW.play_duration_seconds > 2147483647 BEGIN SELECT RAISE(ABORT, 'invalid score play duration'); END;
CREATE TRIGGER scores_play_duration_update_guard BEFORE UPDATE OF play_duration_seconds ON scores WHEN NEW.play_duration_seconds < 0 OR NEW.play_duration_seconds > 2147483647 BEGIN SELECT RAISE(ABORT, 'invalid score play duration'); END;
INSERT INTO score_data_repair_state VALUES(1);
